{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — are we maximizing total profit (unit price minus raw material cost, minus the operating costs of the machines used), or is there a different goal such as maximizing total output or minimizing total cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is this a fixed cost that is incurred whenever that machine is used at all (even for one unit), or is it a variable cost that scales proportionally with the fraction of the machine's hours actually used?"
  ],
  "rationale": "The response asks for a single policy choice regarding the nature of the operating cost (fixed vs. variable), which constitutes one semantically independent question."
}

